1	package server
2	
3	import (
4		"math"
5		"sync"
6		"time"
7	
8		"github.com/entireio/forgemark/internal/bench"
9	)
10	
11	// windowSecs is the rolling-percentile window: latency percentiles in a bucket
12	// event are computed over the OK samples of the last windowSecs seconds, so a
13	// single quiet second doesn't blank the lines while spikes still show quickly.
14	const windowSecs = 10
15	
16	// The live path must stay bounded no matter what the workload does: the
17	// supported envelope (4096 agents, 1ms demo latency floor) reaches millions
18	// of samples per second, where retaining exact latencies and sorting the
19	// full 10s window every snapshot would burn hundreds of MB and whole cores —
20	// the observer throttling the load it measures. Latencies therefore go into
21	// fixed-size log-spaced histograms: O(1) insert with no allocation, ~1KB per
22	// second per op kind, and percentile extraction that walks 256 counters.
23	// Bucket resolution is ~6.7% relative, plenty for live charts; the
24	// authoritative LevelResult still computes exact percentiles from the
25	// engine's own samples.
26	const (
27		latHistBuckets = 256
28		latHistMinMs   = 0.05    // < 50µs collapses into bucket 0
29		latHistMaxMs   = 600_000 // > 10min collapses into the last bucket
30	)
31	
32	var latHistLnGrowth = math.Log(latHistMaxMs/latHistMinMs) / float64(latHistBuckets-2)
33	
34	type latHist [latHistBuckets]uint32
35	
36	// latHistIdx maps a latency to its bucket. Kept separate from the increment
37	// so OnSample can compute it (a math.Log) OUTSIDE the collector mutex,
38	// leaving only plain increments inside the critical section.
39	func latHistIdx(ms float64) int {
40		if ms <= latHistMinMs {
41			return 0
42		}
43		idx := 1 + int(math.Log(ms/latHistMinMs)/latHistLnGrowth)
44		if idx > latHistBuckets-1 {
45			return latHistBuckets - 1
46		}
47		return idx
48	}
49	
50	func (h *latHist) add(ms float64) { h[latHistIdx(ms)]++ }
51	
52	// quantile is the nearest-rank p-th percentile of one histogram (0 if empty).
53	func (h *latHist) quantile(p float64) float64 {
54		total := uint64(0)
55		for _, n := range h {
56			total += uint64(n)
57		}
58		if total == 0 {
59			return 0
60		}
61		rank := uint64(math.Ceil(p / 100 * float64(total)))
62		if rank < 1 {
63			rank = 1
64		}
65		cum := uint64(0)
66		for i, n := range h {
67			cum += uint64(n)
68			if cum >= rank {
69				return latHistValue(i)
70			}
71		}
72		return latHistValue(latHistBuckets - 1)
73	}
74	
75	// maxValue is the representative value of the highest occupied bucket (0 if
76	// empty) — the histogram's stand-in for an exact max.
77	func (h *latHist) maxValue() float64 {
78		for i := latHistBuckets - 1; i >= 0; i-- {
79			if h[i] > 0 {
80				return latHistValue(i)
81			}
82		}
83		return 0
84	}
85	
86	// latHistValue is the representative latency of bucket idx: the geometric
87	// midpoint of its bounds (the edge buckets return their clamp values).
88	func latHistValue(idx int) float64 {
89		switch {
90		case idx <= 0:
91			return latHistMinMs
92		case idx >= latHistBuckets-1:
93			return latHistMaxMs
94		default:
95			return latHistMinMs * math.Exp((float64(idx)-0.5)*latHistLnGrowth)
96		}
97	}
98	
99	// histPercentiles computes nearest-rank p50/p95/p99 over the summed
100	// histograms. Returns zeros when the window holds no samples, matching the
101	// old exact-sample behavior.
102	func histPercentiles(hists ...*latHist) (p50, p95, p99 float64) {
103		var merged [latHistBuckets]uint64
104		total := uint64(0)
105		for _, h := range hists {
106			for i, n := range h {
107				merged[i] += uint64(n)
108				total += uint64(n)
109			}
110		}
111		if total == 0 {
112			return 0, 0, 0
113		}
114		at := func(p float64) float64 {
115			rank := uint64(math.Ceil(p / 100 * float64(total)))
116			if rank < 1 {
117				rank = 1
118			}
119			cum := uint64(0)
120			for i, n := range merged {
121				cum += n
122				if cum >= rank {
123					return latHistValue(i)
124				}
125			}
126			return latHistValue(latHistBuckets - 1)
127		}
128		return at(50), at(95), at(99)
129	}
130	
131	// collector is the live aggregator for one target of one run. It implements
132	// bench.Sink: agents call OnSample concurrently mid-measurement, so it does
133	// only counter and histogram increments under its mutex — no allocation, no
134	// unbounded growth. Once per second the run's ticker calls snapshot, which
135	// rotates the current second into the ring and computes rolling percentiles
136	// from the windowed histograms.
137	type collector struct {
138		mu        sync.Mutex
139		warmup    time.Duration // samples before this offset are excluded (matches the level result)
140		cur       bucket
141		ring      [windowSecs]latHist // one closed second of OK push latencies per slot
142		cloneRing [windowSecs]latHist
143		pos       int
144	}
145	
146	// bucket accumulates one second of samples.
147	type bucket struct {
148		ok, cas, errs     int
149		cloneOK, cloneErr int
150		lat               latHist // OK push latencies (ms)
151		cloneLat          latHist // OK clone latencies (ms)
152	}
153	
154	// BucketStats is one target's slice of a per-second bucket event. Push and
155	// clone ops are reported separately, mirroring LevelResult; the UI picks the
156	// primary series from the workload strategy. Attempt totals are derivable
157	// (ok+cas+err, clone_ok+clone_err), so they aren't carried on the wire.
158	type BucketStats struct {
159		OK  int `json:"ok"`
160		CAS int `json:"cas"`
161		Err int `json:"err"`
162		// Rolling percentiles over the last windowSecs seconds of OK pushes.
163		P50 float64 `json:"p50_ms"`
164		P95 float64 `json:"p95_ms"`
165		P99 float64 `json:"p99_ms"`
166	
167		CloneOK  int     `json:"clone_ok,omitempty"`
168		CloneErr int     `json:"clone_err,omitempty"`
169		CloneP50 float64 `json:"clone_p50_ms,omitempty"`
170		CloneP95 float64 `json:"clone_p95_ms,omitempty"`
171		CloneP99 float64 `json:"clone_p99_ms,omitempty"`
172	}
173	
174	func (c *collector) OnSample(s bench.Sample) {
175		// The bucket index (a math.Log) is computed before taking the lock, so the
176		// critical section is nothing but integer increments — the sink must not
177		// serialize the agents whose throughput it is observing.
178		idx := latHistIdx(float64(s.Dur) / float64(time.Millisecond))
179		c.mu.Lock()
180		defer c.mu.Unlock()
181		// The Sink receives warm-up samples too; drop them so the live counts,
182		// rolling percentiles, and persisted series match the authoritative level
183		// result, which excludes the warm-up window.
184		if s.Offset < c.warmup {
185			return
186		}
187		if s.Op == bench.OpClone {
188			switch s.Res {
189			case bench.OutcomeOK:
190				c.cur.cloneOK++
191				c.cur.cloneLat[idx]++
192			default:
193				c.cur.cloneErr++
194			}
195			return
196		}
197		switch s.Res {
198		case bench.OutcomeOK:
199			c.cur.ok++
200			c.cur.lat[idx]++
201		case bench.OutcomeCAS:
202			c.cur.cas++
203		default:
204			c.cur.errs++
205		}
206	}
207	
208	// snapshot closes out the current second: it returns its counters and the
209	// rolling percentiles over the updated window.
210	func (c *collector) snapshot() BucketStats {
211		c.mu.Lock()
212		b := c.cur
213		c.cur = bucket{}
214		c.ring[c.pos] = b.lat
215		c.cloneRing[c.pos] = b.cloneLat
216		c.pos = (c.pos + 1) % windowSecs
217		// Copy the window (a few KB of fixed arrays) and merge after unlocking, so
218		// the percentile walk never blocks concurrent OnSample calls.
219		ring, cloneRing := c.ring, c.cloneRing
220		c.mu.Unlock()
221	
222		st := BucketStats{
223			OK: b.ok, CAS: b.cas, Err: b.errs,
224			CloneOK: b.cloneOK, CloneErr: b.cloneErr,
225		}
226		hists := make([]*latHist, windowSecs)
227		for i := range ring {
228			hists[i] = &ring[i]
229		}
230		st.P50, st.P95, st.P99 = histPercentiles(hists...)
231		for i := range cloneRing {
232			hists[i] = &cloneRing[i]
233		}
234		st.CloneP50, st.CloneP95, st.CloneP99 = histPercentiles(hists...)
235		return st
236	}
237	
238	// reset clears the bucket and the rolling window and sets the warm-up boundary
239	// for the level about to start, so percentiles never bleed across concurrency
240	// levels and warm-up samples are excluded.
241	func (c *collector) reset(warmup time.Duration) {
242		c.mu.Lock()
243		defer c.mu.Unlock()
244		c.warmup = warmup
245		c.cur = bucket{}
246		c.ring = [windowSecs]latHist{}
247		c.cloneRing = [windowSecs]latHist{}
248		c.pos = 0
249	}
