func (r *Runner) cleanRepoRefs(ctx context.Context, repoPath string, re *regexp.Regexp) (int, error) {
	auth, err := r.creds.basicAuth(ctx, repoPath)
	if err != nil {
		return 0, err
	}
	opts := []gitclient.Option{gitclient.WithHTTPClient(r.httpc), gitclient.WithHTTPAuth(auth)}
	// nodes[0] serves the full advertisement and accepts ref deletes like any
	// push; per-node fan-out exists to spread load, not for correctness.
	remote := git.NewRemote(memory.NewStorage(memory.WithObjectFormat(r.ep.objFmt)), &config.RemoteConfig{
		Name: "origin", URLs: []string{verbatimURLFor(r.ep.nodes[0], repoPath)},
	})
	refs, err := remote.ListContext(ctx, &git.ListOptions{ClientOptions: opts})
	if errors.Is(err, transport.ErrEmptyRemoteRepository) {
		return 0, nil // nothing to clean in an unborn repo
	}
	if err != nil {
		return 0, fmt.Errorf("list refs: %w", err)
	}
	// The remote's default branch can itself be a stale bench ref: the FIRST
	// push to an empty repo promotes that branch to HEAD, and forges then
	// refuse to delete it (GitHub: "refusing to delete the current branch",
	// GitLab: a pre-receive decline) — so asking would fail the sweep on every
	// run, forever. Resolve HEAD from the advertisement (symref target when
	// offered, tip hash otherwise) and leave that ref alone: one permanently
	// pinned ref is a constant, not the unbounded growth this sweep bounds.
	headTarget, headHash := "", plumbing.ZeroHash
	for _, ref := range refs {
		if ref.Name() == plumbing.HEAD {
			if ref.Type() == plumbing.SymbolicReference {
				headTarget = ref.Target().String()
			} else {
				headHash = ref.Hash()
			}
		}
	}
	isDefaultBranch := func(ref *plumbing.Reference) bool {
		if headTarget != "" {
			return ref.Name().String() == headTarget
		}
		// No symref advertised: match by HEAD's tip hash. This can spare an
		// extra ref that merely shares the tip — sparing too much is the safe
		// direction here.
		return headHash != plumbing.ZeroHash && ref.Hash() == headHash
	}
	cutoff := time.Now().Add(-staleAfter)
	var specs []config.RefSpec
	for _, ref := range refs {
		if name := ref.Name().String(); staleRef(re, name, cutoff) && !isDefaultBranch(ref) {
			specs = append(specs, config.RefSpec(":"+name))
		}
	}

