1	// New-run form. Structured around a start-mode chooser (my forges / custom)
2	// so a first-time user has one obvious entry point, with workload tuning and
3	// per-target advanced fields tucked behind disclosures. No credential ever
4	// enters the browser: a target only carries a secret_source (gh | glab |
5	// entire) and the server reads the token from that CLI at run start. A forge
6	// without a supported CLI login is benchmarked from the command line
7	// (forgemark -token-file …), not this form.
8	
9	import { h } from '../dom.js';
10	import { api } from '../api.js';
11	import { targetColor } from '../charts.js';
12	
13	const strategies = [
14	  ['branch', 'branch — one repo, per-agent branches (headline write number)'],
15	  ['repo', 'repo — agents spread across N repos (horizontal scale)'],
16	  ['clone', 'clone — shallow-clone loop (read-side ceiling)'],
17	  ['session', 'session — clone + push checkpoints per session (agent lifecycle)'],
18	];
19	
20	const DEMO_PAIR = [
21	  { name: 'demo-fast', remote: 'demo://fast?p50=60ms&spread=3&err=0.01&cap=400' },
22	  { name: 'demo-slow', remote: 'demo://slow?p50=180ms&spread=4&err=0.03&cas=0.02&cap=120' },
23	];
24	
25	const isDemo = (remote) => /^demo:\/\//i.test((remote || '').trim());
26	
27	let targetSeq = 0;
28	
29	function blankTarget(extra = {}) {
30	  return {
31	    key: ++targetSeq, name: '', remote: '', repos: '', user: '', secret_source: '',
32	    insecure: false, object_format: 'auto', token_url: '', jurisdiction: '', client_id: '', ...extra,
33	  };
34	}
35	
36	export function renderNewRun(app) {
37	  let targets = [blankTarget()];
38	  let mode = null; // null (chooser) | 'forges' | 'custom'
39	  let raceView = false;
40	  let errorBanner = null;
41	
42	  const field = (label, input, cls = '') => h('div', { class: `field ${cls}` }, h('label', {}, label), input);
43	  const inp = (attrs) => h('input', { type: 'text', ...attrs });
44	
45	  // --- workload inputs (persist across mode switches) ---
46	  const w = {
47	    strategy: h('select', { onchange: () => { syncStrategy(); updateWorkloadSummary(); } }, strategies.map(([v, t]) => h('option', { value: v }, t))),
48	    concurrency: inp({ value: '1,8,32', placeholder: 'e.g. 1,8,32,128', oninput: updateWorkloadSummary }),
49	    duration_sec: inp({ value: '60', oninput: updateWorkloadSummary }),
50	    warmup_sec: inp({ value: '10', oninput: updateWorkloadSummary }),
51	    files_min: inp({ value: '1' }),
52	    files_max: inp({ value: '10' }),
53	    file_size: inp({ value: '2048' }),
54	    branch_prefix: inp({ value: '', placeholder: 'e.g. bench/' }),
55	    session_commits: inp({ value: '5' }),
56	    clone_depth: inp({ value: '1' }),
57	    base_ref: inp({ value: '', placeholder: 'default branch' }),
58	  };
59	  const commitFields = h('div', { class: 'grid c3' },
60	    field('Files per commit (min)', w.files_min),
61	    field('Files per commit (max)', w.files_max),
62	    field('Bytes per file', w.file_size));
63	  const cloneFields = h('div', { class: 'grid c3' },
64	    field('Session commits', w.session_commits),
65	    field('Clone depth (0 = full)', w.clone_depth),
66	    field('Base ref', w.base_ref));
67	
68	  function syncStrategy() {
69	    const s = w.strategy.value;
70	    commitFields.style.display = s === 'clone' ? 'none' : '';
71	    cloneFields.style.display = (s === 'clone' || s === 'session') ? '' : 'none';
72	    w.session_commits.parentElement.style.display = s === 'session' ? '' : 'none';
73	  }
74	
75	  const workloadSummary = h('span', { class: 'dsum' });
76	  function updateWorkloadSummary() {
77	    const warm = parseFloat(w.warmup_sec.value || '0');
78	    workloadSummary.textContent =
79	      `${w.strategy.value} · sweep ${w.concurrency.value || '—'} · ${w.duration_sec.value || '—'}s/level` +
80	      (warm > 0 ? ` · ${warm}s warm-up` : '');
81	  }
82	
83	  function applyRacePreset() {
84	    w.strategy.value = 'branch';
85	    w.concurrency.value = '16';
86	    w.duration_sec.value = '60';
87	    w.warmup_sec.value = '0';
88	    w.files_min.value = '1'; w.files_max.value = '3'; w.file_size.value = '1024';
89	    w.branch_prefix.value = 'bench/';
90	    raceView = true;
91	    syncStrategy();
92	    updateWorkloadSummary();
93	  }
94	
95	  // --- targets ---
96	  const targetsBox = h('div');
97	  function renderTargets() {
98	    targetsBox.innerHTML = '';
99	    targets.forEach((t, i) => targetsBox.append(targetCard(t, i)));
100	    updateGate();
101	  }
102	
103	  function targetCard(t, i) {
104	    const bind = (key, input) => {
105	      input.value = t[key];
106	      input.addEventListener('input', () => { t[key] = input.value; });
107	      return input;
108	    };
109	    const insecure = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => { t.insecure = e.target.checked; } });
110	    insecure.checked = t.insecure;
111	
112	    const remoteInput = bind('remote', inp({ placeholder: 'https://gitlab.example — or demo://fast?p50=80ms' }));
113	
114	    // The credential comes from an authenticated CLI the server reads at run
115	    // start, so the token never enters the browser or the request body. Demo
116	    // targets need none. The credential control and the forge-only advanced
117	    // knobs are (re)synced whenever the remote changes: typing a demo:// URL
118	    // into a custom target must drop the credential source and hide the advanced
119	    // fields, or the run would post secret_source and the server would reject it.
120	    const credBox = h('div');
121	    const advanced = h('details', { class: 'disclose', style: { marginTop: '12px', marginBottom: '0' } },
122	      h('summary', {}, 'Advanced'),
123	      h('div', { class: 'dbody' },
124	        h('div', { class: 'grid c3' },
125	          field('Username (token forges ignore it)', bind('user', inp({ placeholder: 'x-access-token' }))),
126	          field('Object format', bind('object_format', h('select', {},
127	            h('option', { value: 'auto' }, 'auto'), h('option', { value: 'sha1' }, 'sha1'), h('option', { value: 'sha256' }, 'sha256')))),
128	          h('div', { class: 'field' }, h('label', {}, 'TLS'),
129	            h('label', { style: { color: 'var(--ink-2)', fontSize: '13px' } }, insecure, ' skip verification (dev hosts)'))),
130	        h('p', { class: 'eyebrow', style: { marginTop: '14px' } }, 'entiredb'),
131	        h('div', { class: 'grid c3' },
132	          field('Token URL', bind('token_url', inp({ placeholder: 'https://…/oauth/token' }))),
133	          field('Jurisdiction', bind('jurisdiction', inp({ placeholder: 'https://us.example.com' }))),
134	          field('Client ID', bind('client_id', inp({ placeholder: 'entire-cli' }))))));
135	
136	    function syncCred() {
137	      const demoish = isDemo(t.remote);
138	      credBox.innerHTML = '';
139	      if (demoish) {
140	        t.secret_source = '';
141	        credBox.append(h('div', { class: 'cred-note' }, 'none needed (demo target)'));
142	      } else {
143	        if (!t.secret_source) t.secret_source = 'gh';
144	        const srcSel = h('select', { onchange: () => { t.secret_source = srcSel.value; } },
145	          h('option', { value: 'gh' }, 'gh CLI login'),
146	          h('option', { value: 'glab' }, 'glab CLI login'),
147	          h('option', { value: 'entire' }, 'entire CLI login'));
148	        srcSel.value = t.secret_source;
149	        credBox.append(srcSel);
150	      }
151	      advanced.style.display = demoish ? 'none' : '';
152	    }
153	    // Swap only credBox/advanced on input, never the remote field itself, so
154	    // focus and caret stay put while typing the demo:// URL.
155	    remoteInput.addEventListener('input', () => { updateGate(); syncCred(); });
156	    syncCred();
157	
158	    return h('div', { class: 'target-card', style: { '--tcolor': targetColor(i) } },
159	      h('div', { class: 'thead' },
160	        h('span', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(i), marginRight: '8px' } }), `Target ${i + 1}`),
161	        targets.length > 1 ? h('button', { class: 'small danger', type: 'button', onclick: () => { targets.splice(i, 1); renderTargets(); } }, 'Remove') : null),
162	      h('div', { class: 'grid c3' },
163	        field('Name (chart label)', bind('name', inp({ placeholder: 'e.g. gitlab-prod' }))),
164	        field('Remote base URL', remoteInput, 'wide')),
165	      h('div', { class: 'grid c2', style: { marginTop: '12px' } },
166	        field('Repos (comma-separated)', bind('repos', inp({ placeholder: 'group/bench.git' }))),
167	        field('Credential source', credBox)),
168	      advanced);
169	  }
170	
171	  const cliNotes = h('div');
172	  async function addFromCLI() {
173	    cliNotes.innerHTML = '';
174	    cliNotes.append(h('div', { class: 'banner' }, 'Detecting gh / glab / entire CLI logins…'));
175	    try {
176	      const sug = await api.localSuggest();
177	      cliNotes.innerHTML = '';
178	      for (const key of ['github', 'gitlab', 'entire']) {
179	        const e = sug[key] || {};
180	        if (e.target) {
181	          const s = e.target;
182	          if (targets.some((t) => t.remote === s.remote && t.repos === (s.repos || []).join(','))) continue;
183	          targets.push(blankTarget({
184	            name: s.name || '', remote: s.remote || '', repos: (s.repos || []).join(','),
185	            user: s.user || '', secret_source: s.secret_source || '',
186	            token_url: s.token_url || '', jurisdiction: s.jurisdiction || '', client_id: s.client_id || '',
187	          }));
188	          if (e.note) cliNotes.append(h('div', { class: 'banner' }, `${s.name}: ${e.note}`));
189	        } else if (e.error) {
190	          cliNotes.append(h('div', { class: 'banner warn' }, `${key}: ${e.error}`));
191	        }
192	      }
193	      if (targets.length > 1 && !targets[0].remote && !targets[0].name) targets.shift();
194	      if (!targets.length) {
195	        cliNotes.append(h('div', { class: 'banner warn' },
196	          'No CLI logins found. Run ', h('code', {}, 'scripts/login.sh'), ' to authenticate gh and entire, then try again.'));
197	        targets = [blankTarget()];
198	      }
199	      renderTargets();
200	    } catch (err) {
201	      cliNotes.innerHTML = '';
202	      cliNotes.append(h('div', { class: 'banner error' }, String(err.message || err)));
203	    }
204	  }
205	
206	  // --- authorization + start (stable elements, re-appended per mode) ---
207	  const startBtn = h('button', { class: 'primary', type: 'submit', disabled: true }, 'Start benchmark');
208	  const confirm = h('input', { type: 'checkbox', id: 'confirm', onchange: updateGate });
209	  const confirmRow = h('div', { class: 'confirm-row' },
210	    confirm,
211	    h('label', { for: 'confirm' }, 'I own this infrastructure or am explicitly authorized to load-test it. A benchmark run is sustained, abusive-looking traffic to any host that has not agreed to it.'));
212	  const raceChk = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => { raceView = e.target.checked; } });
213	
214	  // updateGate keeps the authorization step honest: an all-demo run touches no
215	  // real host, so it needs no confirmation and no checkbox; any real target
216	  // brings the checkbox back and gates Start on it.
217	  function updateGate() {
218	    const withRemote = targets.filter((t) => t.remote.trim());
219	    const allDemo = withRemote.length > 0 && withRemote.every((t) => isDemo(t.remote));
220	    confirmRow.style.display = allDemo ? 'none' : '';
221	    startBtn.disabled = withRemote.length === 0 || (!allDemo && !confirm.checked);
222	    startBtn.textContent = raceView ? 'Start race' : 'Start benchmark';
223	  }
224	
225	  async function submit(ev) {
226	    ev.preventDefault();
227	    if (errorBanner) { errorBanner.remove(); errorBanner = null; }
228	    const showError = (msg) => {
229	      errorBanner = h('div', { class: 'banner error' }, msg);
230	      form.prepend(errorBanner);
231	      window.scrollTo(0, 0);
232	    };
233	    // Reject malformed concurrency instead of silently dropping tokens: an
234	    // empty list would make the server substitute its default [1,8,32,128]
235	    // sweep — a 128-agent surprise the user never asked for.
236	    const concTokens = w.concurrency.value.split(',').map((s) => s.trim()).filter(Boolean);
237	    const concurrency = concTokens.map((s) => parseInt(s, 10));
238	    if (!concurrency.length || concurrency.some((n, i) => !Number.isInteger(n) || n < 1 || String(n) !== concTokens[i])) {
239	      showError(`Concurrency must be comma-separated positive integers (e.g. 1,8,32) — got "${w.concurrency.value}"`);
240	      return;
241	    }
242	
243	    // Validate every numeric field to a finite number before posting. A blank
244	    // or non-numeric entry would parse to NaN, which JSON.stringify emits as
245	    // null; the server reads null as "absent" and quietly substitutes the flag
246	    // default — so a typo'd "6o" duration would silently run for 60s instead of
247	    // erroring. Integer fields must also be whole. Ranges (e.g. min <= max) stay
248	    // the server's job via Validate.
249	    const numSpecs = [
250	      { el: w.duration_sec, label: 'Duration per level', int: false, min: 0, gt0: true },
251	      { el: w.warmup_sec, label: 'Warm-up', int: false, min: 0 },
252	      { el: w.files_min, label: 'Files per commit (min)', int: true, min: 1 },
253	      { el: w.files_max, label: 'Files per commit (max)', int: true, min: 1 },
254	      { el: w.file_size, label: 'Bytes per file', int: true, min: 0 },
255	      { el: w.session_commits, label: 'Session commits', int: true, min: 1 },
256	      { el: w.clone_depth, label: 'Clone depth', int: true, min: 0 },
257	    ];
258	    const nums = new Map();
259	    for (const f of numSpecs) {
260	      const raw = (f.el.value || '').trim();
261	      const v = Number(raw);
262	      if (raw === '' || !Number.isFinite(v) || (f.int && !Number.isInteger(v)) || v < f.min || (f.gt0 && v <= 0)) {
263	        const want = f.int ? 'a whole number' : 'a number';
264	        showError(`${f.label} must be ${want}${f.gt0 ? ' greater than 0' : ` >= ${f.min}`} — got "${f.el.value}"`);
265	        return;
266	      }
267	      nums.set(f.el, v);
268	    }
269	    const num = (el) => nums.get(el);
270	
271	    // Only remote-bearing rows are real targets — a blank card is not posted.
272	    // Compute allDemo over the same set updateGate() uses, so the confirm-gate
273	    // the UI showed and the confirm_authorized we send can't disagree.
274	    const active = targets.filter((t) => t.remote.trim());
275	    if (!active.length) {
276	      showError('Add at least one target with a remote.');
277	      return;
278	    }
279	    const allDemo = active.every((t) => isDemo(t.remote));
280	    const spec = {
281	      confirm_authorized: confirm.checked || allDemo,
282	      workload: {
283	        strategy: w.strategy.value,
284	        concurrency,
285	        duration_sec: num(w.duration_sec),
286	        warmup_sec: num(w.warmup_sec),
287	        files_min: num(w.files_min), files_max: num(w.files_max), file_size: num(w.file_size),
288	        branch_prefix: w.branch_prefix.value,
289	        session_commits: num(w.session_commits), clone_depth: num(w.clone_depth), base_ref: w.base_ref.value,
290	      },
291	      targets: active.map((t) => ({
292	        name: t.name, remote: t.remote,
293	        repos: t.repos.split(',').map((s) => s.trim()).filter(Boolean),
294	        user: t.user, secret_source: t.secret_source,
295	        insecure: t.insecure, object_format: t.object_format,
296	        token_url: t.token_url, jurisdiction: t.jurisdiction, client_id: t.client_id,
297	      })),
298	    };
299	    startBtn.disabled = true;
300	    try {
301	      const res = await api.startRun(spec);
302	      if (res.warnings && res.warnings.length) {
303	        sessionStorage.setItem(`fm-warn-${res.id}`, JSON.stringify(res.warnings));
304	      }
305	      location.hash = raceView ? `#race/${res.id}` : `#run/${res.id}`;
306	    } catch (err) {
307	      updateGate();
308	      showError(String(err.message || err));
309	    }
310	  }
311	
312	  // --- mode chooser & body assembly ---
313	  const body = h('div');
314	
315	  function chooseMode(next) {
316	    mode = next;
317	    errorBanner = null;
318	    if (mode === 'forges') {
319	      targets = [];
320	      applyRacePreset();
321	      addFromCLI();
322	    } else if (mode === 'custom') {
323	      targets = [blankTarget()];
324	      raceView = false;
325	    }
326	    renderBody();
327	  }
328	
329	  function modeCard(ico, title, desc, onclick) {
330	    return h('button', { type: 'button', class: 'mode-card', onclick },
331	      h('span', { class: 'ico' }, ico),
332	      h('span', { class: 'mtitle' }, title),
333	      h('span', { class: 'mdesc' }, desc));
334	  }
335	
336	  const MODE_LABELS = { forges: 'Compare my forges', custom: 'Custom run' };
337	
338	  function renderBody() {
339	    body.innerHTML = '';
340	    if (mode === null) {
341	      body.append(h('div', { class: 'modes' },
342	        modeCard('🏁', 'Compare my forges',
343	          'GitHub, GitLab, and Entire, authenticated from your gh / glab / entire CLI logins. Nothing to paste.',
344	          () => chooseMode('forges')),
345	        modeCard('⚙️', 'Custom run',
346	          'Point at any smart-HTTP forge. Configure targets and the workload by hand.',
347	          () => chooseMode('custom'))));
348	      return;
349	    }
350	
351	    const addButtons = h('div', { class: 'add-row' },
352	      targets.length < 8 ? h('button', { type: 'button', class: 'small', onclick: () => { targets.push(blankTarget()); renderTargets(); } }, '+ Add target') : null,
353	      mode === 'custom' ? h('button', { type: 'button', class: 'small', onclick: addFromCLI }, 'Add from CLI logins') : null,
354	      mode === 'custom' ? h('button', { type: 'button', class: 'small', onclick: () => {
355	        for (const d of DEMO_PAIR) targets.push(blankTarget(d));
356	        if (targets.length > DEMO_PAIR.length && !targets[0].remote && !targets[0].name) targets.shift();
357	        renderTargets();
358	      } }, 'Add demo pair') : null);
359	
360	    body.append(
361	      h('div', { class: 'mode-bar' },
362	        h('span', { class: 'mlabel' }, MODE_LABELS[mode]),
363	        h('button', { type: 'button', class: 'change', onclick: () => { mode = null; renderBody(); } }, 'change')),
364	      h('p', { class: 'eyebrow' }, 'Targets'),
365	      targetsBox,
366	      cliNotes,
367	      addButtons,
368	      h('details', { class: 'disclose', style: { marginTop: '16px' } },
369	        h('summary', {}, 'Workload tuning', workloadSummary),
370	        h('div', { class: 'dbody' },
371	          h('div', { class: 'grid c4' },
372	            field('Strategy', w.strategy, 'wide'),
373	            field('Concurrency sweep', w.concurrency),
374	            field('Duration per level (s)', w.duration_sec),
375	            field('Warm-up (s)', w.warmup_sec),
376	            field('Branch prefix', w.branch_prefix)),
377	          h('div', { style: { marginTop: '12px' } }, commitFields),
378	          h('div', { style: { marginTop: '12px' } }, cloneFields))),
379	      confirmRow,
380	      h('div', { class: 'start-row' },
381	        startBtn,
382	        h('label', { class: 'race-toggle' }, raceChk, 'Open the live race view')));
383	
384	    raceChk.checked = raceView;
385	    renderTargets();
386	    syncStrategy();
387	    updateWorkloadSummary();
388	  }
389	
390	  const form = h('form', { onsubmit: submit },
391	    h('p', { class: 'eyebrow' }, 'ForgeMark'),
392	    h('h1', {}, 'New benchmark run'),
393	    h('p', { class: 'sub' }, 'Drive real git push/clone load against one or more forges and watch them race, live. Pick how you want to start:'),
394	    body);
395	
396	  app.append(form);
397	  renderBody();
398	}
